def _populate_looker_field_attrs(
    attrs: LookerFieldAttributes, obj: LookerField
) -> None:
    """Populate LookerField-specific attributes on the attrs struct."""
    _populate_asset_attrs(attrs, obj)
    attrs.project_name = obj.project_name
    attrs.looker_explore_qualified_name = obj.looker_explore_qualified_name
    attrs.looker_view_qualified_name = obj.looker_view_qualified_name
    attrs.looker_tile_qualified_name = obj.looker_tile_qualified_name
    attrs.looker_look_qualified_name = obj.looker_look_qualified_name
    attrs.looker_dashboard_qualified_name = obj.looker_dashboard_qualified_name
    attrs.model_name = obj.model_name
    attrs.source_definition = obj.source_definition
    attrs.looker_field_data_type = obj.looker_field_data_type
    attrs.looker_times_used = obj.looker_times_used
    attrs.looker_field_is_refined = obj.looker_field_is_refined
    attrs.looker_field_refinement_file_path = obj.looker_field_refinement_file_path
    attrs.looker_field_refinement_line_number = obj.looker_field_refinement_line_number
    attrs.looker_slug = obj.looker_slug
    attrs.catalog_dataset_guid = obj.catalog_dataset_guid


def _extract_looker_field_attrs(attrs: LookerFieldAttributes) -> dict:
    """Extract all LookerField attributes from the attrs struct into a flat dict."""
    result = _extract_asset_attrs(attrs)
    result["project_name"] = attrs.project_name
    result["looker_explore_qualified_name"] = attrs.looker_explore_qualified_name
    result["looker_view_qualified_name"] = attrs.looker_view_qualified_name
    result["looker_tile_qualified_name"] = attrs.looker_tile_qualified_name
    result["looker_look_qualified_name"] = attrs.looker_look_qualified_name
    result["looker_dashboard_qualified_name"] = attrs.looker_dashboard_qualified_name
    result["model_name"] = attrs.model_name
    result["source_definition"] = attrs.source_definition
    result["looker_field_data_type"] = attrs.looker_field_data_type
    result["looker_times_used"] = attrs.looker_times_used
    result["looker_field_is_refined"] = attrs.looker_field_is_refined
    result["looker_field_refinement_file_path"] = (
        attrs.looker_field_refinement_file_path
    )
    result["looker_field_refinement_line_number"] = (
        attrs.looker_field_refinement_line_number
    )
    result["looker_slug"] = attrs.looker_slug
    result["catalog_dataset_guid"] = attrs.catalog_dataset_guid
    return result


