def _looker_field_to_nested(looker_field: LookerField) -> LookerFieldNested:
    """Convert flat LookerField to nested format."""
    attrs = LookerFieldAttributes()
    _populate_looker_field_attrs(attrs, looker_field)
    # Categorize relationships by save semantic (REPLACE, APPEND, REMOVE)
    replace_rels, append_rels, remove_rels = categorize_relationships(
        looker_field, _LOOKER_FIELD_REL_FIELDS, LookerFieldRelationshipAttributes
    )
    return LookerFieldNested(
        guid=looker_field.guid,
        type_name=looker_field.type_name,
        status=looker_field.status,
        version=looker_field.version,
        create_time=looker_field.create_time,
        update_time=looker_field.update_time,
        created_by=looker_field.created_by,
        updated_by=looker_field.updated_by,
        classifications=looker_field.classifications,
        classification_names=looker_field.classification_names,
        meanings=looker_field.meanings,
        labels=looker_field.labels,
        business_attributes=looker_field.business_attributes,
        custom_attributes=looker_field.custom_attributes,
        pending_tasks=looker_field.pending_tasks,
        proxy=looker_field.proxy,
        is_incomplete=looker_field.is_incomplete,
        provenance_type=looker_field.provenance_type,
        home_id=looker_field.home_id,
        delete_handler=looker_field.delete_handler,
        depth=looker_field.depth,
        immediate_upstream=looker_field.immediate_upstream,
        immediate_downstream=looker_field.immediate_downstream,
        attributes=attrs,
        relationship_attributes=replace_rels,
        append_relationship_attributes=append_rels,
        remove_relationship_attributes=remove_rels,
    )


def _looker_field_from_nested(nested: LookerFieldNested) -> LookerField:
    """Convert nested format to flat LookerField."""
    attrs = (
        nested.attributes if nested.attributes is not UNSET else LookerFieldAttributes()
    )
    # Merge relationships from all three buckets
    merged_rels = merge_relationships(
        nested.relationship_attributes,
        nested.append_relationship_attributes,
        nested.remove_relationship_attributes,
        _LOOKER_FIELD_REL_FIELDS,
        LookerFieldRelationshipAttributes,
    )
    # Build kwargs so a field carried by both the top level and the merged
    # relationships (e.g. `meanings`) is passed once, with the relationship
    # value winning — otherwise the constructor gets a duplicate keyword.
    kwargs = {
        "guid": nested.guid,
        "type_name": nested.type_name,
        "status": nested.status,
        "version": nested.version,
        "create_time": nested.create_time,
        "update_time": nested.update_time,
        "created_by": nested.created_by,
        "updated_by": nested.updated_by,
        "classifications": nested.classifications,
        "classification_names": nested.classification_names,
        "meanings": nested.meanings,
        "labels": nested.labels,
        "business_attributes": nested.business_attributes,
        "custom_attributes": nested.custom_attributes,
        "pending_tasks": nested.pending_tasks,
        "proxy": nested.proxy,
        "is_incomplete": nested.is_incomplete,
        "provenance_type": nested.provenance_type,
        "home_id": nested.home_id,
        "delete_handler": nested.delete_handler,
        "depth": nested.depth,
        "immediate_upstream": nested.immediate_upstream,
        "immediate_downstream": nested.immediate_downstream,
    }
    kwargs.update(_extract_looker_field_attrs(attrs))
    kwargs.update(merged_rels)
    return LookerField(**kwargs)


def _looker_field_to_nested_bytes(looker_field: LookerField, serde: Serde) -> bytes:
    """Convert flat LookerField to nested JSON bytes."""
    return serde.encode(_looker_field_to_nested(looker_field))


def _looker_field_from_nested_bytes(data: bytes, serde: Serde) -> LookerField:
    """Convert nested JSON bytes to flat LookerField."""
    nested = serde.decode(data, LookerFieldNested)
    return _looker_field_from_nested(nested)


